            _q(8, 13, 'advanced', 'Một bó hoa gồm 5 bông hoa năm cánh và 1 bông hoa sáu cánh. Tổng cộng có bao nhiêu cánh hoa trên cả bó hoa?', '31 cánh hoa', ['30 cánh hoa', '25 cánh hoa', '36 cánh hoa'],
               '5 × 5 + 6 = 25 + 6 = 31 cánh hoa.', 'Toán & Quan sát'),
